import { getAllTools, getToolOfTheWeek } from "@/lib/tools";
import { ToolGrid } from "@/components/ToolGrid";
import { ToolCard } from "@/components/ToolCard";
import { FeaturedTools } from "@/components/FeaturedTools";
import { FeaturedCarousel } from "@/components/FeaturedCarousel";
import { SponsoredTools } from "@/components/SponsoredTools";
import { TopPicks } from "@/components/TopPicks";
import { ToolOfTheWeek } from "@/components/ToolOfTheWeek";
import { HeroSearchBar } from "@/components/HeroSearchBar";
import { Link } from "@/i18n/routing";
import { ArrowLeft } from "lucide-react";
import { getTranslations } from 'next-intl/server';
import { Suspense } from 'react';
import { Metadata } from 'next';
import { generatePlatformSchema } from "@/lib/schema";

export async function generateMetadata({
  params
}: {
  params: Promise<{ locale: string }>
}): Promise<Metadata> {
  const { locale } = await params;
  return {
    title: "AI Tool Navigator",
    description: "Discover and compare the best AI tools for your workflow.",
    alternates: {
      canonical: `/${locale}`,
    }
  };
}

export default async function Home({
  params,
  searchParams,
}: {
  params: Promise<{ locale: string }>;
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  const { locale } = await params;
  const { search } = await searchParams;
  const hasSearch = !!search;

  const t = await getTranslations('HomePage');
  const tools = await getAllTools(locale);
  const toolOfTheWeek = await getToolOfTheWeek(locale);
  const editorsChoiceSlugs = ['speechify', 'mixo', 'copy-ai', 'basedlabs', 'homesage'];
  const editorsChoiceTools = tools.filter(tool => editorsChoiceSlugs.includes(tool.slug));

  const topPicks = tools
    .filter(t => !t.sponsored && !t.promoted && !t.featured && t.slug !== toolOfTheWeek?.slug)
    .sort((a, b) => b.rating - a.rating)
    .slice(0, 6);

  const platformSchema = generatePlatformSchema(t('description'), locale);

  return (
    <div className="bg-white dark:bg-black min-h-screen transition-colors duration-300">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(platformSchema) }}
      />
      <div className="mx-auto max-w-7xl px-6 py-24 sm:py-32 lg:px-8">
        <div className="mx-auto max-w-2xl text-center mb-16">
          <h1 className="text-4xl font-extrabold tracking-tight text-zinc-900 sm:text-6xl dark:text-zinc-50">
            {t('title')}
          </h1>
          <p className="mt-6 text-lg leading-8 text-zinc-600 dark:text-zinc-400">
            {t('description')}
          </p>
          <HeroSearchBar />
        </div>

        {!hasSearch && (
          <>
            {/* Sponsored Tools Section */}
            <SponsoredTools tools={tools} />

            {/* Tool of the Week Section */}
            <ToolOfTheWeek tool={toolOfTheWeek} />

            {/* Featured Comparison Banner */}
            <div className="mb-16">
              <Link href="/tools/claude-cowork-vs-google-antigravity" className="block group">
                <div className="relative overflow-hidden rounded-3xl bg-zinc-900 px-6 py-10 sm:px-12 sm:py-16 shadow-2xl transition-all hover:scale-[1.01] dark:bg-zinc-800">
                  <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
                    <div className="text-left max-w-xl">
                      <span className="inline-flex items-center rounded-full bg-blue-500/10 px-3 py-1 text-sm font-semibold text-blue-400 ring-1 ring-inset ring-blue-500/20 mb-6">
                        {t('featuredComparison')}
                      </span>
                      <h2 className="text-3xl font-bold tracking-tight text-white sm:text-4xl">
                        Claude Cowork vs. Google Antigravity
                      </h2>
                      <p className="mt-4 text-lg text-zinc-400">
                        Which &quot;AI Colleague&quot; wins in 2026? We break down the performance, pricing, and capabilities of the two biggest agentic platforms.
                      </p>
                    </div>
                    <div className="flex-shrink-0">
                      <div className="rounded-full bg-white/10 p-4 ring-1 ring-white/20 group-hover:bg-white/20 transition-colors">
                        <ArrowLeft className="h-8 w-8 text-white rotate-180" />
                      </div>
                    </div>
                  </div>
                  {/* Background Glow */}
                  <div className="absolute -right-24 -top-24 h-96 w-96 rounded-full bg-blue-500/10 blur-3xl" />
                  <div className="absolute -left-24 -bottom-24 h-96 w-96 rounded-full bg-purple-500/10 blur-3xl" />
                </div>
              </Link>
            </div>

            {/* Trending Tools Carousel */}
            <FeaturedCarousel tools={tools} />

            {/* Featured Tools Section */}
            <FeaturedTools tools={tools} />

            {/* Top Picks Section */}
            <TopPicks tools={topPicks} />

            {/* Editor's Choice Section */}
            {editorsChoiceTools.length > 0 && (
              <div className="mb-16">
                <h2 className="text-2xl font-bold tracking-tight text-zinc-900 dark:text-zinc-50 mb-6 flex items-center gap-2">
                  <span className="text-yellow-500">★</span> {t('editorsChoice')}
                </h2>
                <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
                  {editorsChoiceTools.map((tool) => (
                    <div key={tool.slug} className="flex flex-col h-full">
                      <ToolCard tool={tool} />
                    </div>
                  ))}
                </div>
              </div>
            )}
          </>
        )}

        <Suspense fallback={<div className="py-12 text-center">Loading tools...</div>}>
          <ToolGrid tools={tools} hideSearch={hasSearch} priority={hasSearch} />
        </Suspense>
      </div>
    </div>
  );
}

import { getPostBySlug, getAllPosts } from "@/lib/posts";
import { notFound } from "next/navigation";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import remarkDirective from "remark-directive";
import { remarkRelatedPost } from "@/lib/remark-related-post";
import { remarkComparisonTable } from "@/lib/remark-comparison-table";
import { remarkYoutube } from "@/lib/remark-youtube";
import rehypeSlug from "rehype-slug";
import { routing, Link } from "@/i18n/routing";
import { Calendar, User, Clock } from "lucide-react";
import { Metadata } from "next";
import { Breadcrumbs, BreadcrumbItem } from "@/components/Breadcrumbs";
import { getTranslations } from "next-intl/server";
import Image from "next/image";
import { extractHeadings } from "@/lib/markdown";
import { TableOfContents } from "@/components/TableOfContents";
import { ShareButtons } from "@/components/ShareButtons";
import { ReadingProgressBar } from "@/components/ReadingProgressBar";
import { RelatedPost } from "@/components/RelatedPost";
import { ComparisonTable } from "@/components/ComparisonTable";
import { YouTubeEmbed } from "@/components/YouTubeEmbed";
import { generateArticleSchema, generateBreadcrumbSchema } from "@/lib/schema";
import { getToolOfTheWeek, getAllTools, ToolMetadata } from "@/lib/tools";
import { ToolOfTheWeekSidebar } from "@/components/ToolOfTheWeekSidebar";
import { HeaderLinkButton } from "@/components/HeaderLinkButton";
import { rehypeAdInjection } from "@/lib/rehype-ad-injection";
import { DynamicAdUnit } from "@/components/DynamicAdUnit";

export async function generateStaticParams() {
  const params = [];
  for (const locale of routing.locales) {
    const posts = await getAllPosts(locale);
    for (const post of posts) {
      params.push({ locale, slug: post.slug });
    }
  }
  return params;
}

export async function generateMetadata(
  { params }: { params: Promise<{ slug: string, locale: string }> }
): Promise<Metadata> {
  const { slug, locale } = await params;
  const post = await getPostBySlug(slug, locale);

  if (!post) {
    return {
      title: 'Post Not Found',
    }
  }

  const title = `${post.metadata.title} - AI Tool Navigator Blog`;
  const description = post.metadata.excerpt;

  return {
    title,
    description,
    alternates: {
      canonical: `/${locale}/blog/${slug}`,
    },
    openGraph: {
      title,
      description,
      type: 'article',
      publishedTime: post.metadata.date,
      authors: [post.metadata.author],
      url: `/${locale}/blog/${slug}`,
    },
    twitter: {
      card: 'summary_large_image',
      title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: { params: Promise<{ slug: string, locale: string }> }) {
  const { slug, locale } = await params;
  const post = await getPostBySlug(slug, locale);
  const tBreadcrumbs = await getTranslations('Breadcrumbs');
  const tBlog = await getTranslations('BlogPage');
  const tShare = await getTranslations('ShareButtons');

  if (!post) {
    notFound();
  }

  const { metadata, content } = post;
  const headings = extractHeadings(content);
  const url = `${process.env.NEXT_PUBLIC_SITE_URL}/${locale}/blog/${slug}`;
  const schema = generateArticleSchema({
    title: metadata.title,
    description: metadata.excerpt,
    url: url,
    image: metadata.image,
    datePublished: metadata.date,
    dateModified: metadata.date,
    author: metadata.author,
    readingTime: metadata.readingTime,
    tags: metadata.tags
  });

  const breadcrumbItems: BreadcrumbItem[] = [
    { label: tBreadcrumbs('home'), href: '/' },
    { label: tBreadcrumbs('blog'), href: '/blog' },
    { label: metadata.title },
  ];

  const breadcrumbSchema = generateBreadcrumbSchema(breadcrumbItems, locale);

  // Fetch recent posts
  const allPosts = await getAllPosts(locale);
  const recentPosts = allPosts
    .filter((p) => p.slug !== slug)
    .slice(0, 5);

  const toolOfTheWeek = await getToolOfTheWeek(locale);
  const allTools = await getAllTools(locale);

  const dateLocale = locale === 'ja' ? 'ja-JP' : 'en-US';

  const components = {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-unused-vars
    h1: ({node: _node, children, id, ...props}: any) => (
      <h1 id={id} className="scroll-mt-24 group relative flex items-center" {...props}>
        <span>{children}</span>
        {id && <HeaderLinkButton id={id} />}
      </h1>
    ),
    // eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-unused-vars
    h2: ({node: _node, children, id, ...props}: any) => (
      <h2 id={id} className="scroll-mt-24 group relative flex items-center" {...props}>
        <span>{children}</span>
        {id && <HeaderLinkButton id={id} />}
      </h2>
    ),
    // eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-unused-vars
    h3: ({node: _node, children, id, ...props}: any) => (
      <h3 id={id} className="scroll-mt-24 group relative flex items-center" {...props}>
        <span>{children}</span>
        {id && <HeaderLinkButton id={id} />}
      </h3>
    ),
    // eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-unused-vars
    h4: ({node: _node, children, id, ...props}: any) => (
      <h4 id={id} className="scroll-mt-24 group relative flex items-center" {...props}>
        <span>{children}</span>
        {id && <HeaderLinkButton id={id} />}
      </h4>
    ),
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    'related-post': (props: any) => {
      const { slug } = props;
      const post = allPosts.find((p) => p.slug === slug);
      if (!post) return null;
      return <RelatedPost post={post} />;
    },
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    'comparison-table': (props: any) => {
      const { tools } = props;
      if (!tools) return null;
      const slugs = (tools as string).split(',').map(s => s.trim());
      const toolsData = slugs
        .map(slug => allTools.find((t) => t.slug === slug))
        .filter((t): t is ToolMetadata => t !== undefined);

      if (toolsData.length === 0) return null;

      return <ComparisonTable tools={toolsData} />;
    },
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    'youtube-embed': (props: any) => {
        return <YouTubeEmbed {...props} />;
    },
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    'ad-slot': ({ index }: { index: number | string }) => (
      <DynamicAdUnit
        index={Number(index) - 1}
        type="content"
        slot="content"
        className="my-8"
      />
    ),
  };

  return (
    <div className="bg-white dark:bg-black min-h-screen py-12 transition-colors duration-300">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(schema) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbSchema) }}
      />
      <ReadingProgressBar />
      <div className="mx-auto max-w-7xl px-6 lg:px-8">
        <Breadcrumbs items={breadcrumbItems} />

        <div className="mt-8 lg:grid lg:grid-cols-12 lg:gap-8">
            <main className="lg:col-span-8">
                <article>
                    <header className="mb-10 text-center">
                        <div className="flex items-center justify-center gap-4 text-sm text-zinc-500 dark:text-zinc-400 mb-4 flex-wrap">
                            <div className="flex items-center gap-1">
                                <Calendar className="h-4 w-4" />
                                <time dateTime={metadata.date}>
                                    {new Date(metadata.date).toLocaleDateString(dateLocale, { year: 'numeric', month: 'long', day: 'numeric' })}
                                </time>
                            </div>
                            {metadata.readingTime > 0 && (
                                <>
                                    <span>•</span>
                                    <div className="flex items-center gap-1">
                                        <Clock className="h-4 w-4" />
                                        <span>{tBlog('readingTime', { minutes: metadata.readingTime })}</span>
                                    </div>
                                </>
                            )}
                            <span>•</span>
                            <div className="flex items-center gap-1">
                                <User className="h-4 w-4" />
                                <span>{metadata.author}</span>
                            </div>
                        </div>
                        <h1 className="text-3xl font-bold tracking-tight text-zinc-900 dark:text-white sm:text-5xl mb-6">
                            {metadata.title}
                        </h1>
                        {metadata.tags && metadata.tags.length > 0 && (
                            <div className="flex flex-wrap justify-center gap-2">
                                {metadata.tags.map((tag) => (
                                    <span key={tag} className="inline-flex items-center rounded-full bg-blue-50 px-2.5 py-0.5 text-xs font-medium text-blue-700 ring-1 ring-inset ring-blue-700/10 dark:bg-blue-400/10 dark:text-blue-400 dark:ring-blue-400/30">
                                        {tag}
                                    </span>
                                ))}
                            </div>
                        )}
                        <div className="flex justify-center mt-6">
                            <ShareButtons
                                url={url}
                                title={metadata.title}
                                twitterText={tShare('twitterSharePost', { postTitle: metadata.title })}
                            />
                        </div>
                    </header>

                    <div className="prose prose-lg prose-zinc dark:prose-invert">
                        <ReactMarkdown
                            remarkPlugins={[remarkGfm, remarkDirective, remarkRelatedPost, remarkComparisonTable, remarkYoutube]}
                            rehypePlugins={[rehypeSlug, rehypeAdInjection]}
                            components={components}
                        >
                            {content}
                        </ReactMarkdown>
                    </div>
                </article>
            </main>

            <aside className="lg:col-span-4 space-y-8">
                 <div className="sticky top-24 space-y-8">
                    <div className="hidden lg:block space-y-8">
                        <TableOfContents headings={headings} />
                        <div>
                            <h3 className="font-semibold text-zinc-900 dark:text-zinc-100 mb-4 uppercase tracking-wider text-xs">
                                {tShare('shareThisPost')}
                            </h3>
                            <ShareButtons
                                url={url}
                                title={metadata.title}
                                twitterText={tShare('twitterSharePost', { postTitle: metadata.title })}
                            />
                        </div>
                    </div>

                    <DynamicAdUnit index={0} type="sidebar" slot="sidebar" />

                    <ToolOfTheWeekSidebar tool={toolOfTheWeek} />

                    <div>
                         <h3 className="text-xl font-semibold mb-6 text-zinc-900 dark:text-zinc-100">
                            {tBlog('recentPosts')}
                         </h3>
                         <ul className="space-y-6">
                            {recentPosts.map((post, index) => (
                                <li key={post.slug} className="group">
                                    <Link href={`/blog/${post.slug}`} className="flex gap-4">
                                         {post.image && (
                                             <div className="relative w-24 h-24 flex-shrink-0 overflow-hidden rounded-lg bg-zinc-100 dark:bg-zinc-800">
                                                <Image
                                                    src={post.image}
                                                    alt={post.title}
                                                    fill
                                                    priority={index < 2}
                                                    className="object-cover group-hover:scale-105 transition-transform duration-300"
                                                />
                                             </div>
                                         )}
                                         <div className="flex flex-col justify-center">
                                             <h4 className="text-sm font-medium text-zinc-900 dark:text-zinc-100 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors line-clamp-2">
                                                {post.title}
                                             </h4>
                                             <time className="text-xs text-zinc-500 mt-1 block">
                                                {new Date(post.date).toLocaleDateString(dateLocale, { year: 'numeric', month: 'long', day: 'numeric' })}
                                             </time>
                                         </div>
                                    </Link>
                                </li>
                            ))}
                         </ul>
                    </div>
                 </div>
            </aside>
        </div>
      </div>
    </div>
  );
}

import { getAllTools } from "@/lib/tools";
import { ToolGrid } from "@/components/ToolGrid";
import { getTranslations } from 'next-intl/server';
import { notFound } from "next/navigation";
import { CATEGORY_MAPPINGS } from "@/lib/categories";
import { Breadcrumbs, BreadcrumbItem } from "@/components/Breadcrumbs";
import { HeroSearchBar } from "@/components/HeroSearchBar";
import { generateBreadcrumbSchema, generateCollectionPageSchema } from "@/lib/schema";

export async function generateStaticParams() {
  return Object.keys(CATEGORY_MAPPINGS).map((slug) => ({
    slug,
  }));
}

export async function generateMetadata({ params }: { params: Promise<{ slug: string, locale: string }> }) {
    const { slug, locale } = await params;

     // Validate slug for metadata as well
    if (!Object.keys(CATEGORY_MAPPINGS).includes(slug)) {
        return {
            title: 'Category Not Found',
        };
    }

    const t = await getTranslations({locale, namespace: 'CategoryPage'});

    // Type assertion or safe access
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const titleKey = `${slug}_title` as any; 
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const descriptionKey = `${slug}_description` as any;

    const title = t(titleKey);
    const description = t(descriptionKey);
    const fullTitle = `${title} - AI Tool Navigator`;

    return {
        title: fullTitle,
        description: description,
        alternates: {
            canonical: `/${locale}/category/${slug}`,
        },
        openGraph: {
            title: fullTitle,
            description: description,
            type: 'website',
            url: `/${locale}/category/${slug}`,
        },
        twitter: {
            card: 'summary_large_image',
            title: fullTitle,
            description: description,
        },
    }
}

export default async function CategoryPage({
  params
}: {
  params: Promise<{ locale: string; slug: string }>
}) {
  const { locale, slug } = await params;

  // Validate slug
  if (!Object.keys(CATEGORY_MAPPINGS).includes(slug)) {
    notFound();
  }

  const t = await getTranslations('CategoryPage');
  const tBreadcrumbs = await getTranslations('Breadcrumbs');

  // Get the categories for the current slug
  const targetCategories = CATEGORY_MAPPINGS[slug as keyof typeof CATEGORY_MAPPINGS];

  // Fetch all tools and filter
  const tools = await getAllTools(locale);
  const filteredTools = tools.filter((tool) => 
    targetCategories.includes(tool.category)
  );

  // Get localized title and description
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const title = t(`${slug}_title` as any);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const description = t(`${slug}_description` as any);

  const breadcrumbItems: BreadcrumbItem[] = [
    { label: tBreadcrumbs('home'), href: '/' },
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    { label: tBreadcrumbs(slug as any) },
  ];

  const jsonLd = generateBreadcrumbSchema(breadcrumbItems, locale);
  const collectionSchema = generateCollectionPageSchema({
    name: title,
    description: description,
    url: `${process.env.NEXT_PUBLIC_SITE_URL}/${locale}/category/${slug}`,
    itemCount: filteredTools.length
  });

  return (
    <div className="bg-white dark:bg-black min-h-screen transition-colors duration-300">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(collectionSchema) }}
      />
      <div className="mx-auto max-w-7xl px-6 py-24 sm:py-32 lg:px-8">
        <Breadcrumbs items={breadcrumbItems} />
        <div className="mx-auto max-w-2xl text-center mb-16">
          <h1 className="text-4xl font-extrabold tracking-tight text-zinc-900 sm:text-6xl dark:text-zinc-50">
            {title}
          </h1>
          <p className="mt-6 text-lg leading-8 text-zinc-600 dark:text-zinc-400">
            {description}
          </p>
          <HeroSearchBar />
        </div>

        <ToolGrid tools={filteredTools} hideSearch={true} priority={true} />
      </div>
    </div>
  );
}

"use client";

import { Link } from '@/i18n/routing';
import { ToolMetadata } from '@/lib/tools';
import { cn } from '@/lib/utils';
import { Rating } from '@/components/Rating';
import { useCompare } from '@/context/CompareContext';
import { MouseEvent } from 'react';
import { useTranslations } from 'next-intl';
import Image from 'next/image';

export function ToolCard({ tool, priority }: { tool: ToolMetadata; priority?: boolean }) {
  const { selectedSlugs, toggleTool } = useCompare();
  const isSelected = selectedSlugs.includes(tool.slug);
  const t = useTranslations('ToolCard');

  const handleCompareClick = (e: MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    toggleTool(tool.slug);
  };

  return (
    <div className={cn(
        "group relative flex flex-col justify-between overflow-hidden rounded-2xl border bg-white shadow-sm transition-all hover:shadow-md dark:bg-zinc-900/50 dark:hover:bg-zinc-900",
        isSelected
          ? "border-blue-500 ring-1 ring-blue-500 dark:border-blue-400 dark:ring-blue-400"
          : tool.sponsored
          ? "border-amber-400 ring-1 ring-amber-400/50 dark:border-amber-500 dark:ring-amber-500/50 bg-amber-50/30 dark:bg-amber-900/10"
          : "border-zinc-200 dark:border-zinc-800"
    )}>
      {tool.image && (
        <div className="relative h-48 w-full overflow-hidden bg-zinc-100 dark:bg-zinc-800">
          <Image
            src={tool.image}
            alt={tool.title}
            fill
            priority={priority}
            className="object-cover transition-transform duration-300 group-hover:scale-105"
          />
        </div>
      )}
      <div className="flex flex-col justify-between flex-grow p-6">
        <div>
          <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                  <span className="inline-flex items-center rounded-full bg-blue-50 px-2.5 py-0.5 text-xs font-medium text-blue-700 ring-1 ring-inset ring-blue-700/10 dark:bg-blue-400/10 dark:text-blue-400 dark:ring-blue-400/30">
                  {tool.category}
                  </span>
                  {tool.sponsored && (
                    <span className="inline-flex items-center rounded-full bg-amber-100 px-2.5 py-0.5 text-xs font-bold text-amber-800 ring-1 ring-inset ring-amber-600/20 dark:bg-amber-400/10 dark:text-amber-500 dark:ring-amber-400/20 uppercase tracking-wide">
                      {t('sponsored')}
                    </span>
                  )}
                  {tool.featured && (
